using System;using UnityEngine;
namespace LWS.TruckMusicalParking.Editor {public static class ParkingFixtures {public static void Run(){int n=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Parking fixture: "+label);n++;};var g=new GameObject("Temporary footprint fixture");try{var body=g.AddComponent<Rigidbody>();body.isKinematic=true;var box=g.AddComponent<BoxCollider>();box.size=new Vector3(1.5f,1,3);check(ParkingRules.Contains(box,body,Vector3.zero,Quaternion.identity,new Vector2(4.8f,7.5f)),"whole centered body fits");body.position=Vector3.right*1.9f;check(!ParkingRules.Contains(box,body,Vector3.zero,Quaternion.identity,new Vector2(4.8f,7.5f)),"center alone cannot claim partial footprint");body.position=Vector3.zero;body.rotation=Quaternion.Euler(0,45,0);check(ParkingRules.Contains(box,body,Vector3.zero,Quaternion.identity,new Vector2(4.8f,7.5f)),"angled footprint inside");body.position=Vector3.right*1.5f;check(!ParkingRules.Contains(box,body,Vector3.zero,Quaternion.identity,new Vector2(4.8f,7.5f)),"angled protrusion rejected");body.rotation=Quaternion.identity;body.position=Vector3.right*1.70f;check(ParkingRules.Contains(box,body,Vector3.zero,Quaternion.identity,new Vector2(4.8f,7.5f)),"paint thickness tolerance");body.position=Vector3.right*1.85f;check(!ParkingRules.Contains(box,body,Vector3.zero,Quaternion.identity,new Vector2(4.8f,7.5f)),"tolerance cannot admit clear protrusion");}finally{UnityEngine.Object.DestroyImmediate(g);}check(ParkingRules.BetterClaim(1,7,2,0,0),"earlier stable claim wins");check(ParkingRules.BetterClaim(1,4,1,1,3)&&!ParkingRules.BetterClaim(1,1,1,4,3),"seeded simultaneous priority");var active=new bool[8];var secured=new int[8];var owners=new int[8];for(int i=0;i<8;i++){active[i]=true;secured[i]=owners[i]=-1;}var r=ParkingRules.Resolve(active,secured,owners);check(r.Replay&&r.Remaining==8&&r.EliminatedMask==0,"nobody captured replays same roster");secured[2]=1;owners[1]=2;secured[5]=0;owners[0]=5;r=ParkingRules.Resolve(active,secured,owners);check(!r.Replay&&r.Remaining==2&&r.SecuredMask==36&&ParkingRules.Count(r.EliminatedMask)==6&&r.Winner<0,"all six unsecured eliminated atomically");active[0]=false;secured[0]=2;owners[2]=0;r=ParkingRules.Resolve(active,secured,owners);check(r.Remaining==2&&(r.SecuredMask&1)==0,"eliminated stale owner excluded");secured[5]=1;r=ParkingRules.Resolve(active,secured,owners);check(r.Remaining==1&&r.Winner==2,"mismatched duplicate ownership cannot survive");check(ParkingRules.InBand(new Vector3(30,0,0))&&!ParkingRules.InBand(Vector3.zero),"marked circling band");check(ParkingRules.InBand(new Vector3(30*(ParkingRules.InnerBand-.02f),0,0)),"small boundary tolerance");Debug.Log("PARKING_RULE_FIXTURES_PASS count="+n);}}}
